export const plan = {
  vpc: "10.0.0.0/16",
  subnets: [
    { name: "publica-a", cidr: "10.0.0.0/24" },
    { name: "publica-b", cidr: "10.0.1.0/24" },
    { name: "privada-a", cidr: "10.0.8.0/22" },
    { name: "privada-b", cidr: "10.0.12.0/22" },
  ],
};

spec.code:
const subnet = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["publica-a", "publica-b"]) {
  const usable = aws.cidr.usableAddresses(subnet(name).cidr);
  assert.ok(usable >= 250, name + " ofrece " + usable + " direcciones utilizables y se piden 250");
}

for (const { name, cidr } of plan.subnets) {
  const reserved = aws.cidr.reservedAddresses(cidr);
  assert.strictEqual(reserved.length, 5, name + " debe reservar cinco direcciones");
  for (const address of reserved) {
    assert.ok(aws.cidr.contains(cidr, address + "/32"), address + " no pertenece a " + cidr);
  }
}

const subnet = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["privada-a", "privada-b"]) {
  const usable = aws.cidr.usableAddresses(subnet(name).cidr);
  assert.ok(usable >= 1000, name + " ofrece " + usable + " direcciones utilizables y se piden 1000");
}

const subnets: { name: string; cidr: string }[] = plan.subnets;
for (const [index, first] of subnets.entries()) {
  assert.ok(aws.cidr.contains(plan.vpc, first.cidr), first.name + " queda fuera de la VPC");
  for (const second of subnets.slice(index + 1)) {
    assert.ok(!aws.cidr.overlaps(first.cidr, second.cidr), first.name + " se solapa con " + second.name);
  }
}

const subnet = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["publica-a", "publica-b"]) {
  assert.ok(aws.cidr.usableAddresses(subnet(name).cidr) <= 507, name + " es más grande de lo necesario");
}
for (const name of ["privada-a", "privada-b"]) {
  assert.ok(aws.cidr.usableAddresses(subnet(name).cidr) <= 4091, name + " es más grande de lo necesario");
}
